(()=>{const S=__SB;const c=S.CAMPS[0];S.P.hp=S.P.maxHp=1e6;S.tp(c.x+3,c.z+6);for(const e of S.E){if(e.camp===0){e.aggro=true;e.alertT=0;e.state='combat';}}S.sim(60);
 const res=[];for(let r=0;r<3;r++){S.KEYS.KeyW=r%2==0;const t0=performance.now();S.sim(600);res.push((performance.now()-t0)/600);}S.KEYS.KeyW=false;
 const near=S.E.filter(e=>e.active&&!e.dead).length;
 let t0=performance.now();for(let i=0;i<6;i++)S.Post.render(0);const ren=(performance.now()-t0)/6;
 return 'logic ms/frame '+res.map(v=>v.toFixed(2)).join(' / ')+' (active enemies '+near+') | render ms (swiftshader) '+ren.toFixed(0)+' | calls '+S.renderer.info.render.calls+' tris '+(S.renderer.info.render.triangles/1000).toFixed(0)+'k';})()

